package android.graphics;
public abstract class Shader {public enum TileMode{CLAMP}Matrix local;public void setLocalMatrix(Matrix m){local=new Matrix(m.value);}java.awt.Paint transformed(java.awt.Paint p){if(local==null)return p;if(p instanceof java.awt.LinearGradientPaint){java.awt.LinearGradientPaint v=(java.awt.LinearGradientPaint)p;return new java.awt.LinearGradientPaint(v.getStartPoint(),v.getEndPoint(),v.getFractions(),v.getColors(),v.getCycleMethod(),v.getColorSpace(),local.value);}java.awt.RadialGradientPaint v=(java.awt.RadialGradientPaint)p;return new java.awt.RadialGradientPaint(v.getCenterPoint(),v.getRadius(),v.getFocusPoint(),v.getFractions(),v.getColors(),v.getCycleMethod(),v.getColorSpace(),local.value);}abstract java.awt.Paint paint();}
